<?php
$pid = project_id();
$purchase = one("SELECT COALESCE(SUM(total),0) amount FROM expenses WHERE project_id=? AND status='active'", [$pid])['amount'];
$work = one("SELECT COALESCE(SUM(w.amount),0) amount FROM contract_work_costs w JOIN contracts c ON c.id=w.contract_id WHERE c.project_id=? AND w.status='active'", [$pid])['amount'];
$paid = one("SELECT COALESCE(SUM(amount),0) amount FROM payments WHERE project_id=? AND status='active'", [$pid])['amount'];
$purchaseDue = one("SELECT COALESCE(SUM(GREATEST(0,e.total-COALESCE(a.amount,0))),0) amount FROM expenses e LEFT JOIN (SELECT a.expense_id,SUM(a.amount) amount FROM payment_allocations a JOIN payments p ON p.id=a.payment_id AND p.status='active' GROUP BY a.expense_id) a ON a.expense_id=e.id WHERE e.project_id=? AND e.status='active'",[$pid])['amount'];
$contractBalance = one("SELECT COALESCE(SUM(GREATEST(0,COALESCE(w.amount,0)-COALESCE(a.amount,0))),0) due, COALESCE(SUM(GREATEST(0,COALESCE(a.amount,0)-COALESCE(w.amount,0))),0) prepaid FROM contracts c LEFT JOIN (SELECT contract_id,SUM(amount) amount FROM contract_work_costs WHERE status='active' GROUP BY contract_id) w ON w.contract_id=c.id LEFT JOIN (SELECT a.contract_id,SUM(a.amount) amount FROM payment_allocations a JOIN payments p ON p.id=a.payment_id AND p.status='active' GROUP BY a.contract_id) a ON a.contract_id=c.id WHERE c.project_id=?",[$pid]);
$advance = one("SELECT COALESCE(SUM(GREATEST(0,p.amount-COALESCE(a.amount,0))),0) amount FROM payments p LEFT JOIN (SELECT payment_id,SUM(amount) amount FROM payment_allocations GROUP BY payment_id) a ON a.payment_id=p.id WHERE p.project_id=? AND p.status='active'",[$pid])['amount'];
$kinds = rows("SELECT c.kind, SUM(l.total) amount FROM expense_items l JOIN expenses e ON e.id=l.expense_id JOIN categories c ON c.id=l.category_id WHERE e.project_id=? AND e.status='active' GROUP BY c.kind",[$pid]);
$kindTotals = array_column($kinds,'amount','kind');
$monthStart = date('Y-m-01'); $monthEnd = date('Y-m-t');
$month = one("SELECT (SELECT COALESCE(SUM(total),0) FROM expenses WHERE project_id=? AND status='active' AND expense_date BETWEEN ? AND ?) + (SELECT COALESCE(SUM(w.amount),0) FROM contract_work_costs w JOIN contracts c ON c.id=w.contract_id WHERE c.project_id=? AND w.status='active' AND w.cost_date BETWEEN ? AND ?) amount",[$pid,$monthStart,$monthEnd,$pid,$monthStart,$monthEnd])['amount'];
$cards = ['Recorded expenses'=>bcadd($purchase,$work,2),'Amount paid'=>$paid,'Outstanding'=>bcadd($purchaseDue,$contractBalance['due'],2),'Unallocated advances'=>$advance,'Material expenses'=>$kindTotals['material']??'0','Labour / Theka expenses'=>bcadd($kindTotals['labour']??'0',$work,2),"This month's expenses"=>$month];
?>
<div class="d-flex justify-content-between align-items-center mb-3"><h1 class="h3">Dashboard</h1><a class="btn btn-primary" href="index.php?page=expenses&add=1">Quick Add Expense</a></div>
<div class="row g-3 mb-3"><?php foreach($cards as $label=>$amount): ?><div class="col-6 col-lg-3"><div class="card h-100"><div class="card-body"><div class="text-muted"><?=e($label)?></div><strong class="fs-5"><?=money($amount)?></strong></div></div></div><?php endforeach ?></div>
<p class="text-muted">Contract prepayments: <?=money($contractBalance['prepaid'])?>. Agreed contract commitments are excluded from recorded expenses.</p>
<div class="row g-3"><div class="col-lg-6"><h2 class="h5">Category breakdown</h2><div class="table-responsive"><table class="table table-striped"><thead><tr><th>Category</th><th>Expense</th></tr></thead><tbody>
<?php $breakdown=rows("SELECT c.name,SUM(l.total) amount FROM expense_items l JOIN expenses e ON e.id=l.expense_id JOIN categories c ON c.id=l.category_id WHERE e.project_id=? AND e.status='active' GROUP BY c.id,c.name ORDER BY amount DESC",[$pid]); foreach($breakdown as $r): ?><tr><td><?=e($r['name'])?></td><td><?=money($r['amount'])?></td></tr><?php endforeach ?>
<tr><td>Recognized Theka work</td><td><?=money($work)?></td></tr></tbody></table></div></div>
<div class="col-lg-6"><h2 class="h5">Work type breakdown</h2><div class="table-responsive"><table class="table table-striped"><thead><tr><th>Work type</th><th>Expense</th></tr></thead><tbody>
<?php foreach(rows("SELECT name,SUM(amount) amount FROM (SELECT t.name,SUM(l.total) amount FROM expense_items l JOIN expenses e ON e.id=l.expense_id JOIN work_types t ON t.id=l.work_type_id WHERE e.project_id=? AND e.status='active' GROUP BY t.id,t.name UNION ALL SELECT t.name,SUM(w.amount) amount FROM contract_work_costs w JOIN contracts c ON c.id=w.contract_id JOIN work_types t ON t.id=c.work_type_id WHERE c.project_id=? AND w.status='active' GROUP BY t.id,t.name) x GROUP BY name ORDER BY amount DESC",[$pid,$pid]) as $r): ?><tr><td><?=e($r['name'])?></td><td><?=money($r['amount'])?></td></tr><?php endforeach ?></tbody></table></div></div></div>
<h2 class="h5 mt-3">Recent expenses</h2><div class="table-responsive"><table class="table table-striped"><thead><tr><th>Date</th><th>Expense / work</th><th>Supplier / contractor</th><th>Amount</th></tr></thead><tbody>
<?php $recent=rows("SELECT e.id,e.expense_date date,'Purchase' title,c.name,e.total amount,'expenses' page FROM expenses e LEFT JOIN contacts c ON c.id=e.contact_id WHERE e.project_id=? AND e.status='active' UNION ALL SELECT c.id,w.cost_date date,c.title,n.name,w.amount,'contracts' page FROM contract_work_costs w JOIN contracts c ON c.id=w.contract_id JOIN contacts n ON n.id=c.contact_id WHERE c.project_id=? AND w.status='active' ORDER BY date DESC,id DESC LIMIT 10",[$pid,$pid]); foreach($recent as $r): ?><tr><td><?=e($r['date'])?></td><td><a href="index.php?page=<?=e($r['page'])?>&view=<?=(int)$r['id']?>"><?=e($r['title'])?> #<?=(int)$r['id']?></a></td><td><?=e($r['name']??'—')?></td><td><?=money($r['amount'])?></td></tr><?php endforeach; if(!$recent): ?><tr><td colspan="4">No recorded expenses.</td></tr><?php endif ?></tbody></table></div>
<h2 class="h5 mt-3">Recent payments</h2><div class="table-responsive"><table class="table table-striped"><thead><tr><th>Date</th><th>Recipient</th><th>Method</th><th>Amount</th></tr></thead><tbody>
<?php $recentPayments=rows("SELECT p.*,c.name FROM payments p LEFT JOIN contacts c ON c.id=p.contact_id WHERE p.project_id=? AND p.status='active' ORDER BY p.payment_date DESC,p.id DESC LIMIT 10",[$pid]); foreach($recentPayments as $r): ?><tr><td><a href="index.php?page=payments&view=<?=(int)$r['id']?>"><?=e($r['payment_date'])?></a></td><td><?=e($r['name']??'—')?></td><td><?=e($r['method'])?></td><td><?=money($r['amount'])?></td></tr><?php endforeach; if(!$recentPayments): ?><tr><td colspan="4">No payments.</td></tr><?php endif ?></tbody></table></div>
